import{_ as t,o as i,c as o,a2 as a}from"./chunks/framework.D5wUhsuj.js";const h=JSON.parse('{"title":"PhyAgentOS 开发者手册","description":"","frontmatter":{},"headers":[],"relativePath":"zh/03-developer-manual.md","filePath":"zh/03-developer-manual.md"}'),l={name:"zh/03-developer-manual.md"};function n(d,e,s,r,c,p){return i(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="phyagentos-开发者手册" tabindex="-1">PhyAgentOS 开发者手册 <a class="header-anchor" href="#phyagentos-开发者手册" aria-label="Permalink to &quot;PhyAgentOS 开发者手册&quot;">​</a></h1><p><a href="/docs/en/03-developer-manual">English</a> · <a href="/docs/">文档索引</a></p><blockquote><p>文档版本：1.0.0。</p></blockquote><h2 id="_1-开发不变量" tabindex="-1">1. 开发不变量 <a class="header-anchor" href="#_1-开发不变量" aria-label="Permalink to &quot;1. 开发不变量&quot;">​</a></h2><ol><li>机器人执行只有一条物理路径：<code>ForgeToolClient → Gateway Tool API → ToolEndpoint</code>；</li><li>AgentTask 聚合规划、证据和判定，但不执行机器人；</li><li><code>binding_id</code>、<code>task_id</code>、<code>revision_id</code>、record ID、<code>caller_id</code>、<code>invocation_id</code> 与 <code>attempt_id</code> 相互独立；</li><li>Forge ToolResult 与 invocation events 是权威执行事实；</li><li>Action/Session admission、cancel/stop 接受、timeout 和 <code>unknown</code> 都不能证明物理停止；</li><li>通用 Agent tools、verification、experience、evolution 与动态 MCP 保持独立；</li><li>Runtime 制品必须通过有界归档与摘要校验后才能安装。</li></ol><h2 id="_2-模块地图" tabindex="-1">2. 模块地图 <a class="header-anchor" href="#_2-模块地图" aria-label="Permalink to &quot;2. 模块地图&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">模块</th><th style="text-align:left;">职责</th></tr></thead><tbody><tr><td style="text-align:left;"><code>agent/loop.py</code></td><td style="text-align:left;">现有 Agent Loop、通用工具、动态 MCP、Forge tools 注册、上下文与生命周期</td></tr><tr><td style="text-align:left;"><code>agent/tools/forge_tool_api.py</code></td><td style="text-align:left;">受治理的 Query/Action/Session Tool API Agent wrapper</td></tr><tr><td style="text-align:left;"><code>agent/tools/forge_task.py</code></td><td style="text-align:left;">五个 AgentTask 生命周期工具</td></tr><tr><td style="text-align:left;"><code>forge/tool_client.py</code></td><td style="text-align:left;">严格异步 HTTP client 与响应校验</td></tr><tr><td style="text-align:left;"><code>forge/binding.py</code>、<code>forge/task.py</code></td><td style="text-align:left;">不可变 Runtime/ToolSpec binding、AgentTask model/store、证据、验证与恢复</td></tr><tr><td style="text-align:left;"><code>forge/observation.py</code>、<code>forge/evidence.py</code></td><td style="text-align:left;">best-effort 图像/state 采集与 artifact 写入</td></tr><tr><td style="text-align:left;"><code>skill_runtime/</code></td><td style="text-align:left;">manifest、catalog、安全归档、installer、Registry、state、Runtime manager 与 availability</td></tr><tr><td style="text-align:left;"><code>agent/experience/</code></td><td style="text-align:left;">activation、episode、assessment、Lesson、Skill candidate 与 evolution</td></tr><tr><td style="text-align:left;"><code>verification/</code></td><td style="text-align:left;">公共任务、证据、请求、verdict 契约与 Verification Service</td></tr></tbody></table><h2 id="_3-forge-tool-api-client" tabindex="-1">3. Forge Tool API client <a class="header-anchor" href="#_3-forge-tool-api-client" aria-label="Permalink to &quot;3. Forge Tool API client&quot;">​</a></h2><p><code>ForgeToolClient</code> 只接受 <code>ok=true</code> 且 <code>data</code> 为 object 的 JSON envelope。错误保留 HTTP status、 error code、retryability 以及响应中已有的 invocation identity。</p><table tabindex="0"><thead><tr><th style="text-align:left;">操作</th><th style="text-align:left;">HTTP 契约</th></tr></thead><tbody><tr><td style="text-align:left;">列出 Tools</td><td style="text-align:left;"><code>GET /tools</code> → 200</td></tr><tr><td style="text-align:left;">读取 ToolSpec</td><td style="text-align:left;"><code>GET /tools/{tool_id}</code> → 200</td></tr><tr><td style="text-align:left;">读取 context</td><td style="text-align:left;"><code>GET /tools/{tool_id}/context</code> → 200</td></tr><tr><td style="text-align:left;">调用 Query</td><td style="text-align:left;">解析 ToolSpec 后 <code>POST /tools/{endpoint_id}/{operation}:invoke</code> → 200</td></tr><tr><td style="text-align:left;">接纳 Action</td><td style="text-align:left;"><code>POST /tools/{tool_id}:invoke</code> → 202</td></tr><tr><td style="text-align:left;">Action status</td><td style="text-align:left;"><code>GET /invocations/{invocation_id}</code> → 200</td></tr><tr><td style="text-align:left;">Action result</td><td style="text-align:left;"><code>GET /invocations/{invocation_id}/result</code> → 200 或 pending 202</td></tr><tr><td style="text-align:left;">请求 cancel</td><td style="text-align:left;"><code>POST /invocations/{invocation_id}/cancel</code> → 200 或 accepted 202</td></tr><tr><td style="text-align:left;">接纳 Session</td><td style="text-align:left;"><code>POST /tools/{tool_id}:invoke</code> → 202</td></tr><tr><td style="text-align:left;">停止 Session</td><td style="text-align:left;"><code>POST /invocations/{invocation_id}/stop</code> → 200 或 accepted 202</td></tr></tbody></table><p>路径组件经过 percent encoding。PAOS 生成 <code>caller_id</code>，并在 Action/Session admission 前与 intent 一同持久化。Admission 必须包含非空 <code>invocation_id</code>，Action 还要求 <code>attempt_id</code>。 Timeout 形成 unknown record，恢复不会重复 POST。</p><h2 id="_4-agent-tools" tabindex="-1">4. Agent tools <a class="header-anchor" href="#_4-agent-tools" aria-label="Permalink to &quot;4. Agent tools&quot;">​</a></h2><p>Task lifecycle：</p><ul><li><code>forge_task_create(task_description, verification, activation_id)</code>；</li><li><code>forge_task_get(task_id)</code>；</li><li><code>forge_task_begin_revision(task_id, reason)</code>；</li><li><code>forge_task_finalize(task_id)</code>；</li><li><code>forge_task_cancel(task_id, reason?)</code>。</li></ul><p>Tool transport：</p><ul><li><code>forge_tool_context(tool_id)</code>；</li><li><code>forge_tool_query(tool_id, arguments, task_id?, timeout_ms?)</code>；</li><li><code>forge_tool_start_action(task_id, tool_id, arguments, timeout_ms?)</code>；</li><li><code>forge_tool_action_status(task_id, invocation_id)</code>；</li><li><code>forge_tool_action_result(task_id, invocation_id)</code>；</li><li><code>forge_tool_cancel_action(task_id, invocation_id)</code>；</li><li><code>forge_tool_start_session(task_id, tool_id, arguments, ownership)</code>；</li><li><code>forge_tool_session_status/result/stop_session(task_id, invocation_id)</code>。</li></ul><p>诊断 Query 与绑定调用使用相同 HTTP 方法；每个变更或任务归因 wrapper 都在网络访问前校验 ownership 与冻结 binding。Tool wrapper 不能自行生成 Gateway identity 或 result。</p><h2 id="_5-agenttask-契约与事务" tabindex="-1">5. AgentTask 契约与事务 <a class="header-anchor" href="#_5-agenttask-契约与事务" aria-label="Permalink to &quot;5. AgentTask 契约与事务&quot;">​</a></h2><p><code>AgentTaskRecord</code> 包含稳定 ID、任务描述、<code>TaskVerificationContract</code>、状态、只追加 PlanRevision、evidence refs、verification attempts、取消状态和时间戳。每个 PlanRevision 都有 自己的 Tool records、verdict 和 verification attempts。</p><p><code>AgentTaskStore</code> 使用 SQLite WAL 与 <code>BEGIN IMMEDIATE</code>。创建时在同一事务内查询非终态任务， 保证跨进程全局单活动槽位。更新写入完整的已校验 record 和 append-only event；业务代码不直接 修改表。</p><p>终态任务状态为 <code>succeeded</code>、<code>failed</code>、<code>cancelled</code>；非终态为 <code>executing</code>、<code>cancelling</code>、 <code>awaiting_replan</code>。Tool status <code>unknown</code> 对聚合记账是终态，但它表示失败，不表示已停止。</p><h2 id="_6-绑定执行生命周期" tabindex="-1">6. 绑定执行生命周期 <a class="header-anchor" href="#_6-绑定执行生命周期" aria-label="Permalink to &quot;6. 绑定执行生命周期&quot;">​</a></h2><ol><li>激活 primary Skill，把其 Runtime/ToolSpec candidate 冻结到 AgentTask revision 1；</li><li>第一次绑定物理执行前进行 best-effort 前置采集；</li><li>通过 ForgeToolClient 调用 Query 或接纳 Action/Session；</li><li>Admission 前持久化 caller intent，再保留 Gateway invocation/attempt 引用；</li><li>仅根据权威 status/result 更新异步 record；</li><li>全部 task-owned 执行终结后，finalize 进行后置采集；</li><li>聚合 Tool records、evidence 与任务契约进行验证；</li><li>持久化 task/revision verdict，并调度唯一终态 experience episode。</li></ol><p>record 一旦终结，后续 observation 不会重写它。Cancellation response 会保存，但 <code>requested</code> 或 <code>accepted</code> 仍使任务保持 <code>cancelling</code>，直到核对并显式 finalize。</p><h2 id="_7-verification-与-recovery" tabindex="-1">7. Verification 与 recovery <a class="header-anchor" href="#_7-verification-与-recovery" aria-label="Permalink to &quot;7. Verification 与 recovery&quot;">​</a></h2><p><code>TaskVerificationContract</code> 继续作为用户级公共契约。Verifier 接收 goal、criteria、 constraints、冻结的 Skill binding、PlanRevision、ToolExecutionRecord、Gateway 终态结果、 before/after evidence、任务历史与冻结的 Skill 作用域建议 Lesson。</p><p>在 recovery 模式下，合法 <code>replan_required</code> verdict 将任务置为 <code>awaiting_replan</code> 并设置 deadline。<code>begin_revision</code> 检查相同 <code>task_id</code>、replan budget、deadline 和任务状态，然后追加 revision。历史 attempts 对 experience analysis 保持可见。Verifier exception 会持久化为失败 attempt；audit 保留执行语义，enforce/recovery 则失败。</p><h2 id="_8-evidence-与-retention" tabindex="-1">8. Evidence 与 retention <a class="header-anchor" href="#_8-evidence-与-retention" aria-label="Permalink to &quot;8. Evidence 与 retention&quot;">​</a></h2><p>Evidence 路径相对工作区并原子写入。进入语义验证前，先检查 bundle 身份、关联质量、 完整性、采集时间窗口以及必需的 kind 和 source；再检查保留 artifact 的路径边界、字节大小、 SHA-256、media type 以及可适用的结构化 JSON。Evidence bundle 记录采集质量与错误，不把 best-effort 采集包装成权威事实。</p><p>Retention 可以按策略移除实体字节，但必须保留 task record、execution references、bundle metadata 和审计所需 tombstone。</p><h2 id="_9-skill-runtime-契约" tabindex="-1">9. Skill Runtime 契约 <a class="header-anchor" href="#_9-skill-runtime-契约" aria-label="Permalink to &quot;9. Skill Runtime 契约&quot;">​</a></h2><p><code>skill.yaml</code> 必须使用 <code>manifest_version: 2</code>，包含目录安全的 name/version、相对 Skill document、HTTP(S) <code>gateway_url</code>、非空 required Tools、至少一个 profile，并拒绝未知字段。 Registry resolver 的 Node 必须包含 artifact identity、version、platform、architecture、 archive type、单一根目录 executable entrypoint 与 SHA-256。</p><p>归档校验拒绝绝对/穿越路径、links、重复或冲突路径、超大文件、展开限制违规、清单缺项与摘要 不一致。Skill/Node installer 先 staging 与校验，再原子替换目标，并支持 rollback。</p><p>RuntimeManager：</p><ol><li>解析已安装 Skill 与 profile；</li><li>物化锁定环境，不修改已安装 Node；摘要覆盖精确 dataflow 路径及其同目录全部普通文件的 SHA-256；</li><li>检查 Dora CLI、dataflow、必需文件和环境；</li><li>拒绝接管已占用地址的非托管 Gateway；</li><li>持久化 <code>starting</code>，并以 <code>bash &lt;bundle&gt;/start.sh &lt;name&gt; &lt;version&gt;</code> 执行可选 Bundle 启动钩子，继承终端 stdio；</li><li>检查本地 Dora 服务，需要时执行 <code>dora up</code>，再启动命名 flow；</li><li>等待 flow、<code>GET /tools</code> 与所有 required Tool contexts；</li><li>持久化 running/failed/stopped state 与生命周期日志。</li></ol><p>dataflow 渲染会解析 <code>FORGE_RUNTIME_BIN</code>、<code>PAOS_SKILL_ROOT</code>、<code>PAOS_SKILL_NAME</code> 与 <code>PAOS_SKILL_VERSION</code>，两个 Skill identity 值也会注入 Dora 进程环境。start、stop、Skill install/update 提交与 remove 共享按 Skill 的非阻塞跨进程锁。锁能证明启动仍在执行时，status 保留 <code>starting</code>；无锁的陈旧 <code>starting</code> 仍按原规则核对。</p><p>当前 Forge Skill 兼容基线为 Dora CLI v0.4.1 与 <code>dora-message</code> v0.7.0。RuntimeManager 要求 兼容的命令行为，但不强制精确语义版本；运维人员必须避免复用协议不匹配的 coordinator/daemon。 Dora 是主机 Runtime 前置条件，不是 Python dependency，也不属于 Skill Bundle。</p><p>存在被追踪的非终态 invocation、Session 或 task binding 时，正常 stop 会被拒绝。Force stop 记录 audit event，不改变 invocation truth。</p><h2 id="_10-registry-与-availability" tabindex="-1">10. Registry 与 availability <a class="header-anchor" href="#_10-registry-与-availability" aria-label="Permalink to &quot;10. Registry 与 availability&quot;">​</a></h2><p>artifact 进入 cache 前必须具备 expected size 与 SHA-256。静态 index 直接提供两者；Registry Node 可以省略重复的 digest 与 size 字段，此时已验证 Skill lock 提供 expected digest，客户端从 Registry 元数据或直接下载端点解析 size。Registry 一旦返回 digest，就必须与 lock 一致。断点续传 内容在安装前再次校验。Registry URL 为空时只允许本地 Bundle 或显式静态 index； <code>PAOS_RESOURCE_REGISTRY_URL</code> 覆盖 <code>resourceRegistry.url</code>。 公网 Registry 按名称查询 Skill；CLI 指定的版本在 Node 解析前与下载 Bundle 的 manifest 校验， 不会拼接到 Registry URL。</p><p><code>discover_active_runtime</code> 核对持久化 state、Dora flow、Gateway health 与 required Tool contexts。availability provider 贯通 SkillsLoader、ExperienceCoordinator 与 SkillActivationManager。Skill 发现顺序为 workspace、installed、built-in。</p><h2 id="_11-experience-与-evolution-接入" tabindex="-1">11. Experience 与 evolution 接入 <a class="header-anchor" href="#_11-experience-与-evolution-接入" aria-label="Permalink to &quot;11. Experience 与 evolution 接入&quot;">​</a></h2><p>全部 Agent tool calls 继续记录。冻结 binding/版本字段关联 AgentTask、revision、invocation 与 attempt。Outcome source 将每个 revision verdict 映射到该 revision 最后一条 execution record，使恢复后的任务同时保留失败与成功语义尝试。</p><p>生成 Lesson 和 Skill update 继续经过去敏、作用域、支持门槛、抽象校验、managed block 替换、原子写、reload validation 与 rollback。Evolution failure 保持 fail-open。</p><h2 id="_12-扩展工作流" tabindex="-1">12. 扩展工作流 <a class="header-anchor" href="#_12-扩展工作流" aria-label="Permalink to &quot;12. 扩展工作流&quot;">​</a></h2><p>新增机器人能力时：</p><ol><li>实现或打包 ToolEndpoint operation；</li><li>发布带精确 schema 与 binding 的 Query/Action/Session ToolSpec；</li><li>在 Gateway 定义 operation <code>max_concurrency</code>；</li><li>在 manifest v2 Bundle 中加入锁定 Node 与 profile 引用；</li><li>测试 binding 漂移、context、invoke、pending、terminal、cancel/stop、ownership 与 unknown；</li><li>在 Skill 中加入工作流指导，不写入任务特定坐标或凭据。</li></ol><p>不要创建第二套 PAOS 执行协议、Agent 直连 Dora 或跨 Tool lease。只有通用 task/Tool API tools 无法表达能力时，才应新增 Agent tool。</p><h2 id="_13-测试门禁" tabindex="-1">13. 测试门禁 <a class="header-anchor" href="#_13-测试门禁" aria-label="Permalink to &quot;13. 测试门禁&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ruff</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PhyAgentOS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compileall</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -q</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PhyAgentOS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pytest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -q</span></span></code></pre></div><p>测试应覆盖响应契约、Session ownership、pending/cancel/stop/timeout/unknown、单活动任务、 诊断 Query、不可变 binding、无 POST 恢复、revision recovery、evidence、按版本 episode、归档 攻击、事务回滚、Registry 校验、Runtime health/切换与模拟工作流。具体硬件/仿真测试以独立安装 匹配制品和 Dora 可用为条件。</p><h2 id="后续阅读" tabindex="-1">后续阅读 <a class="header-anchor" href="#后续阅读" aria-label="Permalink to &quot;后续阅读&quot;">​</a></h2><ul><li><a href="/docs/forge/README_zh">Forge Tool API 接入契约</a></li><li><a href="/docs/user_development_guide/README">集成开发指南</a></li><li><a href="/docs/zh/05-agent-experience-and-skill-evolution">Agent 经验与 Skill 自进化</a></li></ul>`,53)])])}const u=t(l,[["render",n]]);export{h as __pageData,u as default};
